  static DataGrid Grid(string name,int height){var grid=new DataGrid{AutoGenerateColumns=false,CanUserAddRows=false,CanUserDeleteRows=false,IsReadOnly=true,SelectionMode=DataGridSelectionMode.Single,Height=height,MinHeight=100,HeadersVisibility=DataGridHeadersVisibility.Column};System.Windows.Automation.AutomationProperties.SetName(grid,name);return grid;}
  static DataGridTextColumn TextColumn(string title,string binding,int weight){return new DataGridTextColumn{Header=title,Binding=new Binding(binding),Width=new DataGridLength(weight,DataGridLengthUnitType.Star)};}
