  Button Button(Panel parent,string text,Action action){var button=new Button{Content=text,Margin=new Thickness(0,0,8,4)};System.Windows.Automation.AutomationProperties.SetName(button,text);UiHelp.For(button,text);button.Click+=(s,e)=>{if(!busy)action();};parent.Children.Add(button);return button;}
  async Task<DiscoveryResult> FindOnNetworks(CancellationToken ct){
   var networks=selectedNetwork==null?DiscoveryNetwork.Available():new List<DiscoveryNetwork>{selectedNetwork};if(networks.Count==0)throw new IOException("Connect this PC to the telescope's Wi-Fi or your shared LAN, then search again.");
   var found=await Task.WhenAll(networks.Select(n=>Task.Run(()=>TelescopeDiscovery.Find(n,ct),ct)));var result=new DiscoveryResult();foreach(var r in found){result.Warnings.AddRange(r.Warnings);result.Devices.AddRange(r.Devices);}var unique=result.Devices.GroupBy(d=>d.Kind+"|"+d.Host).Select(g=>g.First()).OrderBy(d=>d.Name).ToList();result.Devices.Clear();result.Devices.AddRange(unique);return result;
  }
  async Task Operation(Func<CancellationToken,Task> work,string status){if(busy)return;busy=true;Error.Text="";Status.Text=status;operation=new CancellationTokenSource();UpdateActions();try{await work(operation.Token);}catch(OperationCanceledException){if(!closed)Status.Text="Cancelled. You can search or connect again.";}catch(Exception e){if(!closed){Error.Text=e.Message;Status.Text="Could not complete this step.";}}finally{operation.Dispose();operation=null;busy=false;if(!closed)UpdateActions();}}
  internal async Task Discover(){await Operation(async ct=>{var result=await discovery(ct);if(closed)return;Devices.ItemsSource=result.Devices;Devices.SelectedItem=result.Devices.Count==1?result.Devices[0]:null;Status.Text=result.Devices.Count==0?"No telescopes replied. Check that both devices share the same network. Search again, or open Advanced for manual access.":result.Devices.Count+" telescope(s) found. Select yours and connect.";if(result.Warnings.Count>0)Error.Text=string.Join("\n",result.Warnings.Distinct());},"Finding telescopes on your networks… (about 8 seconds)");}
  internal async Task ConnectSelected(){var selected=Devices.SelectedItem as DiscoveredTelescope;if(selected==null)return;var c=new RemoteConnection{Kind=selected.Kind,Host=selected.Host,Folder=selected.Kind=="Seestar SMB"?@"\\"+selected.Host+@"\EMMC Images":"/",IncludeExisting=includeExisting,PollSeconds=poll,LimitMB=limit,Port=ftpPort,User=ftpUser,Password=ftpPassword};await Connect(selected,c);}
  internal async Task Connect(DiscoveredTelescope selected,RemoteConnection c){await Operation(async ct=>{c.Validate(false);var listing=await Task.Run(()=>{using(var source=sourceFactory(c))return RemoteCaptureCatalog.Browse(source,c,c.Folder,ct);},ct);if(closed)return;connection=c;device=selected;folder=c.Folder;firstListing=listing;basket.Clear();DiscoveryPanel.Visibility=Visibility.Collapsed;ConnectedPanel.Visibility=Visibility.Visible;BrowserPanel.Visibility=Visibility.Collapsed;Files.ItemsSource=null;searchAll=false;ConnectedText.Text="Connected · "+selected.Name+" · "+c.Host;Status.Text="Choose files, search all captures, or start live import."+(c.Kind=="Seestar SMB"?" Enable Save Each Frame in Seestar to save individual exposures.":"");FolderText.Text="Live folder: All captures";ConfigureProfile(selected);},"Connecting to "+selected.Name+"…");}
  void ConfigureProfile(DiscoveredTelescope selected){string make=selected.Kind=="Seestar SMB"?"Seestar":"DWARFLAB";var choices=new List<TelescopeProfile>{new TelescopeProfile{Model="Auto"}};choices.AddRange(saved.Where(p=>TelescopeProfiles.Make(p)==make));Profiles.ItemsSource=choices;var bound=choices.FirstOrDefault(p=>!string.IsNullOrEmpty(selected.Identity)&&p.RemoteIdentity==selected.Identity&&p.SourceMake==make);var compatible=choices.FirstOrDefault(p=>preferred!=null&&p.Id==preferred.Id&&(string.IsNullOrEmpty(selected.Identity)||string.IsNullOrEmpty(p.RemoteIdentity)||p.RemoteIdentity==selected.Identity));Profiles.SelectedItem=bound??compatible??choices[0];string suggested=Util.Safe(selected.Name);if(saved.Any(p=>p.Id.Equals(suggested,StringComparison.OrdinalIgnoreCase))){int n=2;while(saved.Any(p=>p.Id.Equals(suggested+" "+n,StringComparison.OrdinalIgnoreCase)))n++;suggested+=" "+n;}Name.Text=suggested;}
  internal async Task Browse(string target){if(connection==null)return;await Operation(async ct=>{List<Entry> list;if(firstListing!=null&&target==connection.Folder){list=firstListing;firstListing=null;}else list=await Task.Run(()=>{using(var source=sourceFactory(connection))return RemoteCaptureCatalog.Browse(source,connection,target,ct);},ct);if(closed)return;folder=target;searchAll=false;ShowFiles(list,false);Status.Text="Open folders with a double-click or Enter. Tick the captures you want to import.";},"Reading capture folders…");}
  internal async Task Search(){if(connection==null)return;await Operation(async ct=>{var list=await Task.Run(()=>{using(var source=sourceFactory(connection))return RemoteCaptureCatalog.Search(source,connection,connection.Folder,ct);},ct);if(closed)return;list=list.Where(include).ToList();folder=connection.Folder;searchAll=true;basket.Clear();ShowFiles(list,true);Status.Text=list.Count==0?"No supported captures were found. Open Advanced to check the storage location.":list.Count.ToString("N0")+" capture files found. Review the selection before importing.";},"Searching all capture folders…");}
  void ShowFiles(IEnumerable<Entry> entries,bool select){var rows=new List<RemoteCaptureRow>();foreach(var entry in entries.Where(e=>e.Directory||include(e))){var row=new RemoteCaptureRow{Entry=entry,Location=Path.GetDirectoryName(RemoteCapturePaths.Relative(connection,entry.Path))??""};row.Selected=select||basket.ContainsKey(entry.Path);if(row.Selected)basket[entry.Path]=entry;row.PropertyChanged+=(s,e)=>{var changed=(RemoteCaptureRow)s;if(changed.Selected)basket[changed.Entry.Path]=changed.Entry;else basket.Remove(changed.Entry.Path);UpdateActions();};rows.Add(row);}Files.ItemsSource=rows;BrowserPanel.Visibility=Visibility.Visible;FolderText.Text=searchAll?"All captures":folder==connection.Folder?"All captures":RemoteCapturePaths.Relative(connection,folder);}
  async Task OpenFolder(){var row=Files.SelectedItem as RemoteCaptureRow;if(row!=null&&row.Entry.Directory&&!busy)await Browse(row.Entry.Path);}
  void ChooseShown(bool selected){foreach(var row in (Files.ItemsSource as IEnumerable<RemoteCaptureRow>)??Enumerable.Empty<RemoteCaptureRow>())row.Selected=selected;UpdateActions();}
  void UpdateActions(){if(ConnectButton==null||ImportButton==null)return;BusyProgress.Visibility=busy?Visibility.Visible:Visibility.Collapsed;ConnectButton.IsEnabled=!busy&&connection==null&&Devices.SelectedItem!=null;FindButton.IsEnabled=!busy;AdvancedButton.IsEnabled=!busy;SearchButton.IsEnabled=SelectButton.IsEnabled=UpButton.IsEnabled=RootButton.IsEnabled=!busy&&connection!=null;Profiles.IsEnabled=Name.IsEnabled=!busy;Files.IsEnabled=Devices.IsEnabled=!busy;CancelButton.Visibility=busy?Visibility.Visible:Visibility.Collapsed;CancelButton.Content=connection==null?"Cancel search / connection":"Cancel";bool named=Profiles.SelectedItem is TelescopeProfile&&!string.IsNullOrEmpty(((TelescopeProfile)Profiles.SelectedItem).Id)||!string.IsNullOrWhiteSpace(Name.Text);ImportButton.IsEnabled=!busy&&connection!=null&&basket.Count>0&&named;LiveButton.IsEnabled=!busy&&connection!=null&&named;ImportButton.Content=basket.Count==0?"Import selected":"Import "+basket.Count.ToString("N0")+" files";LiveButton.Visibility=connection==null?Visibility.Collapsed:Visibility.Visible;ImportButton.Visibility=connection==null?Visibility.Collapsed:Visibility.Visible;LiveScopeText.Text=connection==null?"":"Live folder: "+(folder==connection.Folder?"All captures":RemoteCapturePaths.Relative(connection,folder))+" · "+(includeExisting?"Existing and new captures":"New captures only");ImportButton.IsDefault=ImportButton.IsEnabled;ConnectButton.IsDefault=ConnectButton.IsEnabled;SelectionText.Text=basket.Count==0?"Choose Select files or Search all to import now.":basket.Count.ToString("N0")+" selected · "+ImportWorkflow.Size(basket.Values.Sum(e=>Math.Max(0,e.Size)))+(RemoteCaptureCatalog.WarnForNetwork(basket.Values)?"\nNetwork imports take longer than USB. Choose fewer files for a quicker import.":"");}
  void Accept(bool live){if(busy||connection==null)return;try{var selected=Profiles.SelectedItem as TelescopeProfile;var profile=selected!=null&&!string.IsNullOrEmpty(selected.Id)?Util.Deserialize<TelescopeProfile>(Util.Serialize(selected)):new TelescopeProfile{Id=Name.Text.Trim(),SessionIdentity=Name.Text.Trim(),Model=ModelFromDiscovery(device.Name),Camera="Auto"};if(string.IsNullOrWhiteSpace(profile.Id))throw new IOException("Enter a name for this physical telescope.");if((selected==null||string.IsNullOrEmpty(selected.Id))&&saved.Any(p=>p.Id.Equals(profile.Id,StringComparison.OrdinalIgnoreCase)))throw new IOException("That telescope is already saved. Select it above or choose another name.");if(!string.IsNullOrEmpty(profile.RemoteIdentity)&&!string.IsNullOrEmpty(device.Identity)&&profile.RemoteIdentity!=device.Identity)throw new IOException("That saved telescope is linked to another device. Choose a new name for this telescope.");var files=basket.Values.ToList();if(!live&&files.Count==0)return;
    if(!live&&RemoteCaptureCatalog.WarnForNetwork(files)&&!LargeImport(Dialog.Window,files).Show())return;
    var c=Util.Deserialize<RemoteConnection>(Util.Serialize(connection));c.IncludeExisting=includeExisting;c.PollSeconds=poll;c.LimitMB=limit;if(live)c.Folder=folder;profile.SourceMake=c.Kind=="Seestar SMB"?"Seestar":"DWARFLAB";if(!string.IsNullOrEmpty(device.Identity))profile.RemoteIdentity=device.Identity;Request=new RemoteImportRequest{Connection=c,Profile=profile,Files=files,Live=live};Dialog.Window.DialogResult=true;
   }catch(Exception e){Error.Text=e.Message;}}
  static string ModelFromDiscovery(string name){string normalized=(name??"").Replace("S50P","S50 Pro").Replace("S30P","S30 Pro");return TelescopeProfiles.Models.FirstOrDefault(m=>m!="Auto"&&m!="Other"&&normalized.IndexOf(m,StringComparison.OrdinalIgnoreCase)>=0)??"Auto";}
  internal static FormWindow LargeImport(Window owner,IEnumerable<Entry> files){var list=files.ToList();var d=new FormWindow(owner,"Large network import",570,410);d.Text("Import "+list.Count.ToString("N0")+" files over the network?",true);d.Text(ImportWorkflow.Size(list.Sum(e=>Math.Max(0,e.Size)))+" selected. Network access takes longer than a USB connection, especially for large batches.");d.Text("Choose fewer captures for a quicker import, or connect the telescope by USB. You can cancel during the import; completed copies are retained and originals stay on the telescope.");d.Accept("Import over network",()=>true);return d;}
  async void Advanced(){var d=new FormWindow(Dialog.Window,"Advanced telescope access",650,720);d.Text("Manual access and network options",true);d.Text("Automatic discovery needs no configuration. Use these options for a hidden network, unusual firmware or a custom capture location.");var kind=d.Select("Telescope",new[]{"Seestar","DWARF"},connection==null?manualKind:connection.Kind=="Seestar SMB"?"Seestar":"DWARF");var host=d.Input("Telescope IPv4 address",connection==null?manualHost:connection.Host);var path=d.Input("Storage path (leave blank for default)",connection==null?manualFolder:connection.Folder);var adapter=d.Select("Discovery network",new[]{"All active networks"}.Concat(DiscoveryNetwork.Available().Select(n=>n.Display)).ToArray(),selectedNetwork==null?"All active networks":selectedNetwork.Display);var port=d.Input("DWARF FTP port",ftpPort.ToString());var user=d.Input("DWARF FTP username",ftpUser);d.Text("DWARF FTP password (kept only for this connection)");var password=new PasswordBox{Password=ftpPassword};d.Add(password);Action ftpVisibility=()=>{bool ftp=Convert.ToString(kind.SelectedItem)=="DWARF";port.IsEnabled=user.IsEnabled=password.IsEnabled=ftp;};kind.SelectionChanged+=(s,e)=>ftpVisibility();ftpVisibility();var interval=d.Input("Live polling interval (seconds)",poll.ToString());var bandwidth=d.Select("Transfer limit",new[]{"1 MB/s","2 MB/s","5 MB/s","Unlimited"},limit==0?"Unlimited":limit+" MB/s");var existing=d.Check("Also import existing captures when live import starts",includeExisting);d.Text("Seestar uses direct, read-only file access. No Windows guest-access or signing-policy changes are required.");var error=new TextBlock{TextWrapping=TextWrapping.Wrap};d.Add(error);d.Accept("Apply",()=>{try{int p,seconds;if(!int.TryParse(port.Text,out p)||!int.TryParse(interval.Text,out seconds))throw new IOException("Enter whole numbers for port and polling interval.");if(p<1||p>65535||seconds<2||seconds>120)throw new IOException("Use port 1–65535 and a polling interval of 2–120 seconds.");manualKind=Convert.ToString(kind.SelectedItem);manualHost=host.Text.Trim();manualFolder=path.Text.Trim();ftpPort=p;ftpUser=user.Text;ftpPassword=password.Password;poll=seconds;string rate=Convert.ToString(bandwidth.SelectedItem);limit=rate=="Unlimited"?0:double.Parse(rate.Split(' ')[0]);includeExisting=existing.IsChecked==true;selectedNetwork=DiscoveryNetwork.Available().FirstOrDefault(n=>n.Display==Convert.ToString(adapter.SelectedItem));return true;}catch(Exception e){error.Text=e.Message;return false;}});if(!d.Show())return;if(!string.IsNullOrEmpty(manualHost)){var manual=new DiscoveredTelescope{Kind=manualKind=="Seestar"?"Seestar SMB":"DWARF FTP",Host=manualHost,Name=manualKind+" (manual)"};var c=new RemoteConnection{Kind=manual.Kind,Host=manualHost,Folder=manualFolder.Length>0?manualFolder:manual.Kind=="Seestar SMB"?@"\\"+manualHost+@"\EMMC Images":"/",Port=ftpPort,User=ftpUser,Password=ftpPassword,PollSeconds=poll,LimitMB=limit,IncludeExisting=includeExisting};await Connect(manual,c);}}
  internal void PreparePreview(DiscoveredTelescope telescope,RemoteConnection c,IEnumerable<Entry> entries){preview=true;connection=c;device=telescope;folder=c.Folder;ConnectedPanel.Visibility=Visibility.Visible;DiscoveryPanel.Visibility=Visibility.Collapsed;ConnectedText.Text="Connected · "+telescope.Name+" · "+c.Host;ConfigureProfile(telescope);ShowFiles(entries,true);UpdateActions();}
  internal bool Show(){return Dialog.Show()&&Request!=null;}
