   string cache=Path.Combine(Path.GetDirectoryName(config),"RemoteDownloads");T("SourceBox").Text=Path.Combine(RemoteCaptureStaging.CacheRoot(cache,request.Connection),"captures");SaveSettings();var repository=repo;int workers=settings.CopyWorkers;bool ignoreFailed=settings.IgnoreFailed,ignoreRaster=settings.IgnoreRasterImports;RemoteArchiveResult result=null;if(request.Live)cancellationMessage="Live import stopped. Completed imports and local downloads are retained; telescope originals are unchanged.";
